package com.bocsoft.sqleditor.execution;
import com.bocsoft.sqleditor.execution.api.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.sql.*;import java.util.*;import org.springframework.stereotype.Component;
@Component public class ResultSetReader {private final JdbcValueEncoder encoder;private final ObjectMapper mapper;public ResultSetReader(JdbcValueEncoder encoder,ObjectMapper mapper){this.encoder=encoder;this.mapper=mapper;}public ReadResult read(ResultSet rs,int rowLimit,long byteLimit)throws SQLException{ResultSetMetaData meta=rs.getMetaData();int count=meta.getColumnCount();List<SqlColumn>columns=new ArrayList<SqlColumn>();for(int i=1;i<=count;i++)columns.add(new SqlColumn(meta.getColumnName(i),meta.getColumnLabel(i),JdbcTypeNames.name(meta.getColumnType(i)),meta.getColumnTypeName(i)));List<List<Object>>rows=new ArrayList<List<Object>>();long bytes=0;boolean truncated=false;while(rs.next()){if(rows.size()>=rowLimit){truncated=true;break;}List<Object>row=new ArrayList<Object>(count);for(int i=1;i<=count;i++)row.add(encoder.encode(rs,i,meta.getColumnType(i)));long size;try{size=mapper.writeValueAsBytes(row).length;}catch(Exception e){throw new SQLException("结果序列化失败");}if(bytes+size>byteLimit){truncated=true;break;}bytes+=size;rows.add(row);}return new ReadResult(columns,rows,truncated,bytes);}public static class ReadResult{private final List<SqlColumn>columns;private final List<List<Object>>rows;private final boolean truncated;private final long bytes;ReadResult(List<SqlColumn>c,List<List<Object>>r,boolean t,long b){columns=c;rows=r;truncated=t;bytes=b;}public List<SqlColumn>getColumns(){return columns;}public List<List<Object>>getRows(){return rows;}public boolean isTruncated(){return truncated;}public long getBytes(){return bytes;}}}
